+        border-radius: 28px;
+        background: rgba(255, 255, 255, 0.9);
+        box-shadow: var(--shadow);
+        backdrop-filter: blur(18px);
+      }
+
+      .card-header {
+        padding: 36px 36px 22px;
+      }
+
+      h1 {
+        margin: 0;
+        font-size: clamp(2rem, 6vw, 3rem);
+        line-height: 1;
+        letter-spacing: -0.06em;
+      }
+
+      .subtitle {
+        margin: 16px 0 0;
+        color: var(--muted);
+        font-size: 1rem;
+        line-height: 1.6;
+      }
+
+      .preferences-form {
+        padding: 6px 36px 36px;
+      }
+
+      .form-field {
+        display: grid;
+        gap: 14px;
+        margin: 0 0 26px;
+        padding: 22px;
+        border: 1px solid var(--border);
+        border-radius: 22px;
+        background: #fbfcff;
+      }
+
+      .question {
+        margin: 0 0 4px;
+        font-size: 1.08rem;
+        font-weight: 750;
+        letter-spacing: -0.02em;
+      }
+
+      .radio-option {
+        position: relative;
+        display: flex;
+        align-items: center;
+        gap: 12px;
+        padding: 16px;
+        border: 1px solid var(--border);
+        border-radius: 16px;
+        background: var(--card);
+        cursor: pointer;
+        transition:
+          border-color 180ms ease,
+          box-shadow 180ms ease,
+          transform 180ms ease;
+      }
+
+      .radio-option:hover {
+        border-color: #c7d2fe;
+        box-shadow: 0 10px 24px rgba(79, 70, 229, 0.09);
+        transform: translateY(-1px);
+      }
+
+      .radio-option input {
+        width: 20px;
+        height: 20px;
+        margin: 0;
+        accent-color: var(--primary);
+      }
+
+      .radio-option:has(input:checked) {
+        border-color: var(--primary);
+        box-shadow: 0 0 0 4px var(--ring);
+      }
+
+      .option-text {
+        font-size: 0.98rem;
+        font-weight: 650;
+      }
+
+      .submit-button {
+        width: 100%;
+        border: 0;
+        border-radius: 16px;
+        padding: 16px 20px;
+        background: linear-gradient(135deg, var(--primary), #7c3aed);
+        color: #ffffff;
+        font: inherit;
+        font-weight: 800;
+        cursor: pointer;
+        box-shadow: 0 16px 30px rgba(79, 70, 229, 0.28);
+        transition:
+          box-shadow 180ms ease,
+          transform 180ms ease,
+          background 180ms ease;
+      }
+
+      .submit-button:hover {
+        background: linear-gradient(135deg, var(--primary-dark), #6d28d9);
+        box-shadow: 0 20px 36px rgba(79, 70, 229, 0.34);
+        transform: translateY(-1px);
+      }
+
+      .submit-button:focus-visible,
+      .radio-option input:focus-visible {
+        outline: 4px solid var(--ring);
+        outline-offset: 3px;
+      }
+
+      @media (max-width: 520px) {
+        .card-header,
+        .preferences-form {
+          padding-left: 22px;
+          padding-right: 22px;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <main id="root"></main>
+
+    <script>
+      const notificationOptions = ["Email", "SMS", "Push Notifications"];
+
+      function RadioOption({ name, value, label, required }) {
+        const id = `${name}-${value.toLowerCase().replace(/\s+/g, "-")}`;
+
+        return `
+          <label class="radio-option" for="${id}">
+            <input type="radio" id="${id}" name="${name}" value="${value}" ${required ? "required" : ""} />
+            <span class="option-text">${label}</span>
+          </label>
+        `;
+      }
+
+      function NotificationQuestion() {
+        return `
+          <div class="form-field">
+            <p class="question">How do you prefer to receive notifications?</p>
+            ${notificationOptions
+              .map((option) =>
+                RadioOption({
+                  name: "notificationPreference",
+                  value: option,
+                  label: option,
+                  required: true,
+                }),
+              )
+              .join("")}
+          </div>
+        `;
+      }
+
+      function PreferencesForm() {
+        return `
+          <form class="preferences-form" action="#" method="post">
+            ${NotificationQuestion()}
+            <button class="submit-button" type="submit">Save preference</button>
+          </form>
+        `;
+      }
+
+      function App() {
+        return `
+          <section class="app-shell">
+            <article class="card">
+              <header class="card-header">
+                <p class="preheading">Notification settings</p>
+                <h1>Choose how we keep in touch</h1>
+                <p class="subtitle">Select one preferred channel so important product updates reach you in the right place.</p>
+              </header>
+              ${PreferencesForm()}
+            </article>
+          </section>
+        `;
+      }
+
+      document.getElementById("root").innerHTML = App();
+    </script>
+  </body>
+</html>
*** End Patch
