     <title>Notification Preferences</title>
     <style>
       :root {
         color-scheme: light;
         --bg: #eef2ff;
         --card: #ffffff;
         --text: #172033;
         --muted: #667085;
         --primary: #4f46e5;
         --primary-dark: #4338ca;
