   </head>
   <body>
     <main id="root"></main>

     <script>
       const notificationOptions = ["Email", "SMS", "Push Notifications"];

       function RadioOption({ name, value, label, required }) {
         const id = `${name}-${value.toLowerCase().replace(/\s+/g, "-")}`;

         return `
           <label class="radio-option" for="${id}">
             <input type="radio" id="${id}" name="${name}" value="${value}" ${required ? "required" : ""} />
             <span class="option-text">${label}</span>
           </label>
         `;
       }

       function NotificationQuestion() {
         return `
           <div class="form-field">
             <p class="question">How do you prefer to receive notifications?</p>
             ${notificationOptions
               .map((option) =>
                 RadioOption({
                   name: "notificationPreference",
                   value: option,
                   label: option,
                   required: true,
                 }),
               )
               .join("")}
           </div>
         `;
       }

       function PreferencesForm() {
         return `
           <form class="preferences-form" action="#" method="post">
             ${NotificationQuestion()}
             <button class="submit-button" type="submit">Save preference</button>
           </form>
         `;
       }

       function App() {
         return `
           <section class="app-shell">
             <article class="card">
               <header class="card-header">
                 <p class="preheading">Notification settings</p>
                 <h1>Choose how we keep in touch</h1>
                 <p class="subtitle">Select one preferred channel so important product updates reach you in the right place.</p>
               </header>
               ${PreferencesForm()}
             </article>
           </section>
         `;
       }

       document.getElementById("root").innerHTML = App();
     </script>
   </body>
 </html>

